    let stage_of = |a: &Attempt| p.stages.iter().find(|s| s.name == a.stage);
    let Some((a, path)) =
        pick(&|a| stage_of(a).is_some() || a.context == "root" || a.context == "joined")
    else {
        return Vec::new();
    };
